import XCTest
@testable import KipurseCore

/// t1275: the phone checks the owner's own SIWE message + signature before it adopts the sign-in owner / wallet. The statement text, the
/// key fingerprint, the EIP-191 hash and the ERC-6492 validator call data must be byte-for-byte the gateway's: the fixture is generated by
/// gateway scripts/t1275-signin-siwe-fixture.mjs (signinStatementFor + siweMessage + viem); the gateway test fails if it is stale.
final class T1275SigninSiweTests: XCTestCase {
  struct St: Decodable { let x, y, fp, statement: String }
  struct Case: Decodable { let owner: String; let x, y: String?; let nonce, issuedAt, message, signature, hash, call: String }
  struct File: Decodable { let validatorKeccak: String; let statements: [St]; let siwe: [Case] }
  func load() throws -> File {
    let u = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("t1275-signin-siwe.json.txt")
    return try JSONDecoder().decode(File.self, from: Data(contentsOf: u))
  }
  func b(_ h: String?) -> [UInt8]? { h.flatMap(Hex.decode) }
  func at(_ c: Case) -> Date { SigninSiwe.date(c.issuedAt)!.addingTimeInterval(60) }
  let ok: SigninSiwe.DeploylessCall = { _ in "0x01" }

  // MARK: one formula with the gateway
  func testStatementAndFingerprintEqualGateway() throws {
    let f = try load(); XCTAssertGreaterThanOrEqual(f.statements.count, 5)
    for s in f.statements {
      let x = b(s.x)!, y = b(s.y)!; XCTAssertEqual(x.count, 32); XCTAssertEqual(y.count, 32)
      XCTAssertEqual(PhoneTrust.fingerprint(x: x, y: y), s.fp); XCTAssertEqual(SigninSiwe.statement(x: x, y: y), s.statement)
    }
    XCTAssertEqual(SigninSiwe.statement(x: nil, y: nil), SigninSiwe.genericStatement)
  }
  func testHashValidatorCallAndParseEqualGateway() throws {
    let f = try load(); XCTAssertGreaterThanOrEqual(f.siwe.count, 7)
    XCTAssertEqual(Hex.encode(Keccak.hash(Hex.decode(SigninSiwe.validatorCode)!)), f.validatorKeccak, "validator bytecode = viem's")
    for c in f.siwe {
      XCTAssertEqual(Hex.encode(SigninSiwe.personalHash(c.message)), c.hash)
      XCTAssertEqual(SigninSiwe.validatorCall(owner: c.owner, hash: b(c.hash)!, signature: c.signature), c.call)
      let p = SigninSiwe.parse(c.message); XCTAssertEqual(p?.address, c.owner); XCTAssertEqual(p?.nonce, c.nonce); XCTAssertEqual(p?.chainId, 8453); XCTAssertEqual(p?.domain, "pay.kipurse.com")
    }
  }
  // MARK: happy path and refusals (mocked RPC)
  func testHappyPathAccepted() async throws {
    let f = try load(); var seen: String? = nil
    for c in f.siwe.prefix(6) {
      let r = await SigninSiwe.check(owner: c.owner, message: c.message, signature: c.signature, x: b(c.x), y: b(c.y), nonce: c.nonce, now: at(c), call: { d in seen = d; return "0x01" })
      XCTAssertNil(r, c.message); XCTAssertEqual(seen, c.call, "the eth_call is the validator over THIS owner / hash / signature")
    }
  }
  func testRefusals() async throws {
    let c = try load().siwe[0]; let x = b(c.x)!, y = b(c.y)!, now = at(c)
    func chk(owner: String? = nil, message: String? = nil, sig: String? = nil, x xx: [UInt8]?? = nil, nonce: String? = nil, host: String = SignHost.apiHost, now n: Date? = nil, call: @escaping SigninSiwe.DeploylessCall = { _ in "0x01" }) async -> String? {
      await SigninSiwe.check(owner: owner ?? c.owner, message: message ?? c.message, signature: sig ?? c.signature, x: xx ?? x, y: y, nonce: nonce ?? c.nonce, host: host, now: n ?? now, call: call)
    }
    let other = "0x2000000000000000000000000000000000000002"
    let r1 = await chk(owner: other); XCTAssertEqual(r1, "owner", "server names an owner the message is not for")
    let r2 = await chk(message: c.message.replacingOccurrences(of: "pay.kipurse.com wants", with: "evil.example wants")); XCTAssertEqual(r2, "domain")
    let r3 = await chk(message: c.message.replacingOccurrences(of: "URI: https://pay.kipurse.com", with: "URI: https://evil.example")); XCTAssertEqual(r3, "uri")
    let r4 = await chk(host: "evil.example"); XCTAssertEqual(r4, "domain")
    var k2 = x; k2[31] ^= 1
    let r5 = await chk(x: .some(k2)); XCTAssertEqual(r5, "statement", "the statement names another phone key")
    let r6 = await chk(x: .some(nil)); XCTAssertEqual(r6, "statement", "a keyed statement while this phone sent no key")
    let r7 = await chk(message: c.message.replacingOccurrences(of: "Chain ID: 8453", with: "Chain ID: 1")); XCTAssertEqual(r7, "chain")
    let r8 = await chk(nonce: "ffffffffffffffffffffffff"); XCTAssertEqual(r8, "nonce", "an old signature replayed under another sign-in")
    let r9 = await chk(now: now.addingTimeInterval(3 * 3600)); XCTAssertEqual(r9, "time")
    let r10 = await chk(now: now.addingTimeInterval(-3600)); XCTAssertEqual(r10, "time", "issued in the future")
    let r11 = await chk(call: { _ in "0x00" }); XCTAssertEqual(r11, "signature", "validator says not valid")
    let r12 = await chk(call: { _ in nil }); XCTAssertEqual(r12, "signature", "nodes disagree / unreachable")
    let r13 = await chk(sig: "0xzz"); XCTAssertEqual(r13, "signature_shape")
    let r14 = await SigninSiwe.check(owner: c.owner, message: nil, signature: c.signature, x: x, y: y, nonce: c.nonce, now: now, call: ok); XCTAssertEqual(r14, "missing", "old server: no message -> refuse")
    let exp = c.message + "\nExpiration Time: 2020-01-01T00:00:00Z"
    let r15 = await chk(message: exp); XCTAssertEqual(r15, "expired")
    let r16 = await chk(message: c.message + "\nEvil Field: 1"); XCTAssertEqual(r16, "parse", "unknown field")
    let r17 = await chk(message: c.message + "\nNonce: abc"); XCTAssertEqual(r17, "parse", "repeated field")
    let r18 = await chk(message: c.message.replacingOccurrences(of: "\n", with: "\r\n")); XCTAssertNil(r18, "CRLF tolerated like the server")
  }
  /// Production wiring: the deployless eth_call goes to two nodes that must answer the same.
  func testTwoNodesMustAgree() async throws {
    let c = try load().siwe[0]; let saved = ChainRPC.transport; defer { ChainRPC.transport = saved }
    func run(_ answers: [String]) async -> String? {
      var i = 0
      ChainRPC.transport = { _, method, params in
        XCTAssertEqual(method, "eth_call"); let o = params.first as? [String: Any]; XCTAssertNil(o?["to"], "deployless: no to"); XCTAssertEqual(o?["data"] as? String, c.call)
        defer { i += 1 }; return answers[min(i, answers.count - 1)] }
      return await SigninSiwe.check(owner: c.owner, message: c.message, signature: c.signature, x: b(c.x), y: b(c.y), nonce: c.nonce, now: at(c))
    }
    let agree = await run(["0x01", "0x01"]); XCTAssertNil(agree)
    let disagree = await run(["0x01", "0x00"]); XCTAssertEqual(disagree, "signature")
    let bothNo = await run(["0x00", "0x00"]); XCTAssertEqual(bothNo, "signature")
  }
  /// The sign-in status now carries the message + signature; verifiedOwner hands back the owner only when every check passes.
  func testStatusResultCarriesProofAndVerifiedOwner() async throws {
    let c = try load().siwe[0]; let W = "0x2000000000000000000000000000000000000002"
    let esc = { (s: String) in s.replacingOccurrences(of: "\n", with: "\\n") }
    let j = try JSONDecoder().decode(JSONValue.self, from: Data(#"{"state":"done","result":"bind","owner":"\#(c.owner)","wallet":"\#(W)","siweMessage":"\#(esc(c.message))","siweSignature":"\#(c.signature)"}"#.utf8))
    let r = try XCTUnwrap(CoinbaseIdentity.Result(j)); XCTAssertEqual(r.siweMessage, c.message); XCTAssertEqual(r.siweSignature, c.signature)
    let good = await SigninSiwe.verifiedOwner(r, x: b(c.x), y: b(c.y), nonce: c.nonce, now: at(c), call: ok); XCTAssertEqual(good, c.owner)
    let bad = await SigninSiwe.verifiedOwner(r, x: b(c.x), y: b(c.y), nonce: c.nonce, now: at(c), call: { _ in "0x00" }); XCTAssertNil(bad)
    let j2 = try JSONDecoder().decode(JSONValue.self, from: Data(#"{"state":"done","result":"bind","owner":"\#(W)","wallet":"\#(W.replacingOccurrences(of: "2", with: "3"))","siweMessage":"\#(esc(c.message))","siweSignature":"\#(c.signature)"}"#.utf8))
    let swapped = await SigninSiwe.verifiedOwner(try XCTUnwrap(CoinbaseIdentity.Result(j2)), x: b(c.x), y: b(c.y), nonce: c.nonce, now: at(c), call: ok); XCTAssertNil(swapped, "server swaps in another owner")
  }
  func testValidatorResultRule() {
    XCTAssertTrue(SigninSiwe.isValid("0x01")); XCTAssertTrue(SigninSiwe.isValid("0x" + String(repeating: "0", count: 63) + "1"))
    for s in ["0x00", "0x", "0x02", "0x0101", nil] as [String?] { XCTAssertFalse(SigninSiwe.isValid(s), s ?? "nil") }
  }
}

/// t1275: the sign-in flow and the opening flow adopt only verified owners (source checks; the app target is not unit-testable here).
final class T1275SigninSourceTests: XCTestCase {
  func src(_ f: String) throws -> String { try String(contentsOfFile: #filePath.replacingOccurrences(of: "Tests/KipurseCoreTests/T1275SigninSiweTests.swift", with: "App/Sources/" + f), encoding: .utf8) }
  func testSigninAdoptsOnlyTheVerifiedOwner() throws {
    let s = try src("CoinbaseSignIn.swift")
    XCTAssertFalse(s.contains("set(r.owner, forKey: CoinbaseIdentity.ownerKey)"), "ownerKey only from the verified owner")
    XCTAssertFalse(s.contains("owner: r.owner, hints"), "chainConfirms only with the verified owner")
    XCTAssertEqual(s.components(separatedBy: "guard let owner = await verifiedOwner(r) else").count - 1, 2, "opened + finish both verify first")
    XCTAssertFalse(s.contains("BiometricGate.unlockContext(reason: T(\"确认这次登录"), "no Face ID at sign-in (0A #2)")
  }
  func testOpeningHasNoUncheckedWalletFallback() throws {
    let s = try src("MainnetViews.swift")
    XCTAssertFalse(s.contains("verifiedW == nil ||")); XCTAssertFalse(s.contains("owner: j[\"owner\"]?.string, path: \"/t/\""))
  }
}
